		stats = &s.stats[idx]
	}

	switch cmd {
	case "GET":
		var reqID string
		if len(args) == 2 {
			reqID = args[1]
			args = args[:1]
		}
		// Busy wait for accurate timing
		start := time.Now()
		deadline := start.Add(s.cfg.GetDelay)
		for time.Now().Before(deadline) {
		}
		elapsed := time.Since(start)
		if stats != nil {
			stats.recordGet(elapsed, false)
		}
		return formatResponse("VALUE", reqID, []byte(args[0]))

	case "SCAN":
		var reqID string
		if len(args) == 3 {
			reqID = args[2]
			args = args[:2]
		}
		limit, err := strconv.Atoi(args[1])
		if err != nil || limit <= 0 {
			if stats != nil {
				stats.recordScan(0, true)
			}
			return formatResponse("ERR", reqID, []byte("invalid scan limit"))
		}
		if limit > s.cfg.MaxScanKeys {
			limit = s.cfg.MaxScanKeys
		}
		// Busy wait for accurate timing
		start := time.Now()
		deadline := start.Add(s.cfg.ScanDelay)
		for time.Now().Before(deadline) {
		}
		elapsed := time.Since(start)
		if stats != nil {
			stats.recordScan(elapsed, false)
		}
		return formatResponse("SCAN", reqID, []byte("EMPTY"))
	default:
		return []byte("ERR unknown command")
	}
}

func (s *Server) openWorker(idx int) (*net.UDPConn, int, error) {
	attachPolicy := s.policy != nil && s.policy.program != nil && idx == 0
	var attachErr error

	lc := net.ListenConfig{Control: func(network, address string, c syscall.RawConn) error {
		return c.Control(func(fd uintptr) {
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEADDR, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEADDR: %w", err)
				return
			}
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEPORT, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEPORT: %w", err)
				return
			}
			if attachPolicy && attachErr == nil {
				if err := s.policy.attach(int(fd)); err != nil {
					attachErr = err
				}
			}
		})
	}}

	pc, err := lc.ListenPacket(context.Background(), "udp", s.cfg.ListenAddr)
	if err != nil {
		return nil, -1, err
	}
	if attachErr != nil {
		pc.Close()
		return nil, -1, attachErr
	}

	udpConn := pc.(*net.UDPConn)
	var fd int
	raw, err := udpConn.SyscallConn()
	if err != nil {
		udpConn.Close()
		return nil, -1, err
	}
	if err := raw.Control(func(value uintptr) {
		fd = int(value)
	}); err != nil {
		udpConn.Close()
		return nil, -1, err
	}

	return udpConn, fd, nil
}

go func(workerID int, conn *net.UDPConn, rng *rand.Rand) {
	defer sendWG.Done()
	buf := make([]byte, 0, 256)
	for {
		if err := limiter.Wait(ctx); err != nil {
			return
		}
		currSeq := atomic.AddUint64(&seq, 1) - 1
		isGet := true
		reqType := "GET"
		if rng.Float64() > *getFrac {
			reqType = "SCAN"
			isGet = false
		}
		// Capture timestamp, build payload, and send immediately
		reqID := makeReqID(time.Now().UnixNano(), currSeq, isGet)
		payload := buildPayload(rng, buf, reqType, reqID, *keyPrefix, *keySpace, *scanLimit)
		if _, err := conn.Write(payload); err != nil {
			logger.Printf("write error (worker=%d): %v", workerID, err)
			buf = payload[:0]
			continue
		}
		atomic.AddInt64(&sentTotal, 1)
		if isGet {
			atomic.AddInt64(&sentGet, 1)
		} else {
			atomic.AddInt64(&sentScan, 1)
		}
		buf = payload[:0]
	}
}(workerID, conn, rng)

